"""RetinaScan XAI: Kaggle Phase 2 runner (generated by kaggle/build_kernel.py --stage phase2).

Takes the trained artifacts from the full-run kernel output (attached as input)
and adds, WITHOUT retraining or refitting anything on test:
  - quality-gate thresholds from TRAIN images (lane B's ml/quality.py, if present)
  - external-dataset evaluation (lane B's ml/prepare_external.py, if configured)
  - re-evaluation reusing the validation-fitted calibration.json
  - degradation test (blur/dark/...) on raw test images
  - serving-consistency check (infer.py vs evaluate.py, self-retrieval)
"""
import base64
import io
import json
import shutil
import subprocess
import sys
import tarfile
import time
from pathlib import Path

CONFIG = json.loads(r'''__CONFIG__''')
CODE_B64 = "__CODE_B64__"

WORK = Path("/kaggle/working")
ART = WORK / "artifacts"
CODE = Path("/tmp/rs_code")
CACHE = Path("/tmp/rs_cache")
EXT = Path("/tmp/rs_ext")


def sh(args, log, check=True):
    print("$", " ".join(map(str, args)), flush=True)
    with open(log, "a") as f:
        p = subprocess.Popen([sys.executable, "-u", *map(str, args)], cwd=CODE, stdout=subprocess.PIPE,
                             stderr=subprocess.STDOUT, text=True)
        for line in p.stdout:
            print(line, end="", flush=True)
            f.write(line)
        rc = p.wait()
    if rc != 0 and check:
        raise SystemExit(f"step failed: {args[0]} (exit {rc}); see {log}")
    return rc


def find_aptos():
    for csv in Path("/kaggle/input").rglob("train.csv"):
        if (csv.parent / "train_images").is_dir():
            return csv, csv.parent / "train_images"
    raise SystemExit("APTOS not found under /kaggle/input")


def find_prev_artifacts():
    for p in Path("/kaggle/input").rglob("model.pt"):
        if (p.parent / "calibration.json").exists() and (p.parent / "splits.csv").exists():
            return p.parent
    raise SystemExit("full-run artifacts (model.pt + calibration.json + splits.csv) not found under /kaggle/input")


def main():
    t0 = time.time()
    c = CONFIG
    for d in (ART, CODE, CACHE, EXT):
        d.mkdir(parents=True, exist_ok=True)
    tarfile.open(fileobj=io.BytesIO(base64.b64decode(CODE_B64))).extractall(CODE)
    log = ART / "phase2.log"
    prev = find_prev_artifacts()
    _, img_dir = find_aptos()
    print(f"phase2 config={c}\nprevious artifacts: {prev}\naptos images: {img_dir}", flush=True)

    # Carry the full-run artifacts forward so this output is a complete set.
    for f in prev.iterdir():
        if f.is_file():
            shutil.copy(f, ART / f.name)
    meta = json.loads((ART / "train_config.json").read_text())
    size, clahe = int(meta["img_size"]), bool(meta.get("clahe", True))
    no_clahe = [] if clahe else ["--no_clahe"]

    # 1. Quality-gate thresholds from TRAIN images only (lane B's quality.py).
    qthr = ""
    if (CODE / "quality.py").exists() and c.get("quality_cmd"):
        args = [a.replace("{IMG_DIR}", str(img_dir)).replace("{SPLITS}", str(ART / "splits.csv"))
                .replace("{OUT}", str(ART)) for a in c["quality_cmd"]]
        sh(["quality.py", *args], log)
        qthr = str(ART / "quality_thresholds.json")
    else:
        print("quality step skipped (quality.py or quality_cmd missing)", flush=True)

    # 2. External dataset (lane B's prepare_external.py).
    ext_args = []
    if c.get("ext_dataset") and (CODE / "prepare_external.py").exists():
        print("inputs:", sorted(str(p) for p in Path("/kaggle/input").glob("*/*"))[:20], flush=True)
        # Mount paths vary between Kaggle versions; find IDRiD by its own label file.
        labels = sorted(Path("/kaggle/input").rglob("*Disease Grading_Training Labels.csv"))
        if not labels:
            raise SystemExit("IDRiD 'Disease Grading_Training Labels.csv' not found under /kaggle/input")
        src = labels[0].parents[1]  # .../B. Disease Grading
        print("IDRiD root:", src, flush=True)
        sh(["prepare_external.py", "--in_dir", src, "--out_dir", EXT], log)
        ext_args = ["--ext_csv", EXT / "external.csv", "--ext_dir", EXT / "images", "--ext_name",
                    c.get("ext_name", "external"), "--ext_cache", "/tmp/rs_ext_cache"]
    else:
        print("external step skipped", flush=True)

    # 3. Re-evaluate with the SAME validation-fitted calibration (+ external if any).
    sh(["cache_images.py", "--splits", ART / "splits.csv", "--img_dir", img_dir, "--cache_dir", CACHE,
        "--size", size, "--which", "val,test", *no_clahe], log)
    shutil.copy(ART / "calibration.json", ART / "calibration_from_full_run.json")
    sh(["evaluate.py", "--ckpt", ART / "model.pt", "--splits", ART / "splits.csv", "--cache_dir", CACHE,
        "--out", ART, "--calibration", ART / "calibration_from_full_run.json", *ext_args], log)

    # 4. Degradation test on raw test images.
    sh(["degrade_test.py", "--ckpt", ART / "model.pt", "--calibration", ART / "calibration.json", "--splits",
        ART / "splits.csv", "--img_dir", img_dir, "--out", ART,
        *(["--quality_thresholds", qthr] if qthr else [])], log)

    # 5. Serving consistency (needs train_index.npz from the full run).
    sh(["check_serving.py", "--artifacts", ART, "--img_dir", img_dir, "--out", ART], log, check=False)

    print(f"PHASE2 DONE in {(time.time() - t0) / 60:.1f} min; artifacts: {sorted(p.name for p in ART.iterdir())}",
          flush=True)


if __name__ == "__main__":
    main()
